32	/**
33	 * A full theme, complete with descriptors. This is the value returned from useAppearance().parsedAppearance, and is
34	 * the main type interacted with within components.
35	 */
36	export type ParsedElements = Record<DescriptorIdentifier, ParsedDescriptor>;
37	export type ParsedLayout = Required<Layout>;
