78	/**
79	 * Used to merge full themes with ParsedElementsFragments. Allows you to combine layoutStyle with multiple visualStyle
80	 * elements.
81	 */
82	export function mergeParsedElementsFragment(...fragments: ParsedElementsFragment[]): ParsedElementsFragment {
83	  const acc: ParsedElementsFragment = {};
84	
85	  fragments.forEach(fragment => {
86	    for (const k in fragment) {
87	      const key = k as keyof ParsedElementsFragment;
88	      if (key in acc) {
89	        acc[key]!.className = [acc[key]?.className, fragment[key]?.className].join(' ');
90	        acc[key]!.style = {
91	          ...acc[key]!.style,
92	          ...fragment[key]?.style,
93	        };
94	      } else {
95	        acc[key] = {
96	          className: fragment[key]?.className,
97	          style: fragment[key]?.style,
98	        };
99	      }
100	    }
101	  });
102	
103	  return acc;
104	}
