106	/**
107	 * Used within components to merge multiple descriptors onto a single element. Result is directly spread onto the element.
108	 */
109	export function mergeDescriptors(...descriptors: (ParsedDescriptor | boolean)[]): PartialDescriptor {
110	  return descriptors.reduce<PartialDescriptor>(
111	    (acc, el) => {
112	      if (typeof el === 'boolean') return acc;
113	      acc.className = [el.descriptor, acc.className, el.className].join(' ');
114	      acc.style = { ...acc.style, ...el.style };
115	      return acc;
116	    },
117	    { className: 'debug', style: {} },
